    for p in v: rs.append(p[0])
    min_r=min(rs); max_r=max(rs); min_c=min(cs); max_c=max(cs)
    # center: line cell nearest to rectangle = min manhattan to any rect cell
    best_c=None; bd=10**9
    for p in best:
        db=min(abs(p[0]-r)+abs(p[1]-c) for r in rs for c in cs)
        if db<bnd: best_c=db; bnd=db
        if db<bnd:
            bnd=db; center=p
    # four arms from center
    for dr,dj in dirs():
        a,b=center[0]+dr,center[1]+dj
        while 0<=a<H and 0<=b<W and I[a][b]!=8:
