t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def f(I):
    H,W=len(I),len(I[0]); out=[r[:] for r in I]
    cnt=collections.Counter(p for r in I for p in r); bg=cnt.most_common(1)[0][0]
    g=collections.defaultdict(list)
    for i in range(H):
        for j in range(W): g[I[i][j]].append((i,j))
    order=sorted(g.items(), key=lambda kv:-len(kv[1]))
    big,gp=order[0]; lin,lpt=order[1]
    P=sorted(lpt,key=lambda q:(q[0],q[1]))
    # anti-diagonal directions through each endpoint; step away from edge/nonbg
    for e in (P[0],P[-1]):
        a,b=e
        for da,db in ((-1,1),(1,-1)):
            y,x=a+da,b+db
            while 0<=y<H and 0<=x<W and I[y][x]==bg:
                out[y][x]=3; y+=da; x+=db
    return out

I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
print('demo:', f(I)==O)
R=f(G['Test input'])
print(json.dumps(R))

